/* ARRIVE logo — the supplied arrive-logo.png (white wordmark + teal pin, transparent), cropped to its bounds and resized.
   Not recoloured, stretched or re-drawn. It is an extracted PNG, NOT a vector master (see Project Instructions §7/§9).
   On white/light surfaces it is always placed on an ARRIVE Blue tile; on blue/navy it is used directly. */
window.ARRIVE_LOGO_WEB = 'data:image/png;base64,';
window.ARRIVE_LOGO_PDF = 'data:image/png;base64,';
window.ARRIVE_LOGO_RATIO = 560/154; /* width / height of the cropped logo */
document.querySelectorAll('img[data-ds-logo]').forEach(function(i){ i.src = window.ARRIVE_LOGO_WEB; });
